package com.bank.recenthire;

import java.time.*;
import java.util.*;
import java.util.logging.*;

public class RecentHireDemo {
    private static final Logger log = Logger.getLogger("RecentHire");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Clock clock = Clock.fixed(Instant.parse("2025-06-01T00:00:00Z"), ZoneOffset.UTC);
        List<Employee> staff = List.of(
            new Employee("Rajesh", LocalDate.parse("2018-03-10")),   // > 5 yrs
            new Employee("Priya", LocalDate.parse("2022-07-01")),    // within 5 yrs
            new Employee("Amit", LocalDate.parse("2020-06-01")));    // exactly 5 yrs cutoff
        RecentHireService service = new RecentHireService(clock);

        List<String> recent = service.joinedWithinYears(staff, 5);
        log.info(() -> "Joined in last 5 years: " + recent);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final LocalDate joinDate;
    Employee(String name, LocalDate joinDate) { this.name = name; this.joinDate = joinDate; }
    String getName() { return name; }
    LocalDate getJoinDate() { return joinDate; }
}

// ─── Would be in service/RecentHireService.java ───
class RecentHireService {
    private final Clock clock;
    RecentHireService(Clock clock) { this.clock = clock; }

    List<String> joinedWithinYears(List<Employee> staff, int years) {
        LocalDate cutoff = LocalDate.now(clock).minusYears(years);   // 5 years ago
        return staff.stream()
            .filter(e -> !e.getJoinDate().isBefore(cutoff))          // on or after cutoff
            .map(Employee::getName)
            .toList();
    }
}
